# Fix-ShiftMismatch.ps1
#
# SHIFT_MISMATCH repair for ShiftEntries WIC_DUTY rows written by an automatic
# SYSTEM_* roster batch with the CENTRE's opening hours instead of the agent's own
# usual shift.
#
# SCOPE   ShiftEntries, ShiftType='WIC_DUTY', ShiftDate in [ScopeFrom..ScopeTo].
#
# A row is REPAIRED only when ALL of these hold:
#   a) SourceModule='Roster' AND AutoGenerated=1 AND ManualChangeBy empty AND
#      the row's RosterBatches.CreatedByKid matches 'SYSTEM_*'
#      (SYSTEM_WICFIX / SYSTEM_BACKUPFIX / SYSTEM_EXT2027 / any other SYSTEM_*);
#   b) ShiftStart-ShiftEnd is EXACTLY the centre's working window for that date
#      (the trace of the bug): either the resolved WicOpeningHours primary
#      interval (OpenTime-CloseTime) or the resolver's DutyWindow;
#   c) the agent has a clear usual shift FOR THAT WEEKDAY: the most frequent
#      ShiftStart-ShiftEnd over the agent's own manual rows (ManualChangeBy set)
#      and WORKING rows of the BaselineWeeks weeks BEFORE the row's date,
#      restricted to the same DayOfWeek, with >= MinOccurrences occurrences and a
#      share >= MinShare. If that weekday has not enough data, the same rule is
#      applied over all days of the same window. If that also yields nothing, the
#      row is NOT touched and goes on the RTM list.
#
# NOT TOUCHED: manual rows, AL/SL/OFF/PH and every other absence, rows without a
# clear usual shift (RTM list), today and past days.
#
# REPAIR
#   ShiftEntries.ShiftStart / ShiftEnd  = the usual shift (c)
#   WicShiftEntries.WorkingShift        = intersection of the new shift with the
#                                         centre's working intervals for that date
#                                         (first overlap start .. last overlap end)
#   ManualChangeBy/At/Note              = provenance of this repair (never S60028)
#   If the intersection is empty the row is NOT changed and goes on the RTM list.
#   Rows whose new shift would equal the old one are left alone.
#
# MODES
#   DryRun (default) : SELECT only. Writes plan CSV + report + examples.
#   Apply            : requires -PlanFile (from the dry run) + -ExpectedFixCount.
#                      Writes the backup directory, then ONE transaction with a
#                      per-row guard (row must still be exactly as in the dry run,
#                      otherwise skipped and listed) and ROLLBACK on any failure.
#
# Mirrors the server rules:
#   WicHoursResolver.Resolve / DutyWindow / Intervals   Backend/Services/WicHoursResolver.cs
#   WicLocationMatcher.MatchesAgentTask/SupportLocation Backend/Services/WicLocationMatcher.cs
#
# Examples:
#   pwsh -File Tools\ShiftMismatchFix\Fix-ShiftMismatch.ps1
#   pwsh -File Tools\ShiftMismatchFix\Fix-ShiftMismatch.ps1 -Apply -ExpectedFixCount 812

[CmdletBinding()]
param(
    [string] $ConnectionString = "Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;",
    [ValidateSet('DryRun','Apply')] [string] $Mode = 'DryRun',
    [string] $ScopeFrom = '2026-10-15',
    [string] $ScopeTo   = '2027-02-28',
    [int]    $BaselineWeeks  = 8,
    [ValidateSet('Row','Today')] [string] $BaselineAnchor = 'Today',
    [int]    $MinOccurrences = 3,
    [double] $MinShare       = 0.60,
    [string] $ManualChangeByKid = 'S69307',
    [string] $OutDir      = 'C:\GSDDashboard_secure\.tmp-shiftfix',
    [string] $RollbackRoot = 'C:\ProgramData\PulseRollback',
    [string] $PlanFile    = '',
    [int]    $ExpectedFixCount = 0,
    [string] $FixNote     = 'SHIFT_MISMATCH repair: SYSTEM_* batch wrote centre hours instead of the agent usual shift',
    [switch] $Apply
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Data
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

if ($Apply) { $Mode = 'Apply' }
$isDryRun = ($Mode -ne 'Apply')

if (-not (Test-Path $OutDir)) { New-Item -ItemType Directory -Path $OutDir -Force | Out-Null }
if ([string]::IsNullOrWhiteSpace($PlanFile)) { $PlanFile = Join-Path $OutDir 'shift-mismatch-plan.csv' }
$ReportFile = Join-Path $OutDir 'shift-mismatch-report.txt'
$AllCsv     = Join-Path $OutDir 'shift-mismatch-all.csv'
$RtmCsv     = Join-Path $OutDir 'shift-mismatch-rtm.csv'

$conn = New-Object System.Data.SqlClient.SqlConnection($ConnectionString)
$conn.Open()

function Invoke-Rows([string]$sql) {
    $cmd = $conn.CreateCommand(); $cmd.CommandText = $sql; $cmd.CommandTimeout = 900
    $rdr = $cmd.ExecuteReader()
    $out = New-Object System.Collections.ArrayList
    while ($rdr.Read()) {
        $h = [ordered]@{}
        for ($i = 0; $i -lt $rdr.FieldCount; $i++) {
            $v = $rdr.GetValue($i); if ($v -is [System.DBNull]) { $v = $null }
            $h[$rdr.GetName($i)] = $v
        }
        [void]$out.Add([pscustomobject]$h)
    }
    $rdr.Close()
    return ,$out
}
function Invoke-Scalar([string]$sql) {
    $cmd = $conn.CreateCommand(); $cmd.CommandText = $sql; $cmd.CommandTimeout = 900
    return $cmd.ExecuteScalar()
}

# ---------------------------------------------------------------------------
# Helpers - byte-for-byte mirrors of the server rules
# ---------------------------------------------------------------------------
# WicLocationMatcher.RepairDoubleEncoding, exactly: only a value that actually
# contains the Windows-1252 mis-decode marker (U+00C3 'Ã') is repaired. A generic
# UTF8/1252 round-trip would CORRUPT a correctly encoded value ("Saarbrücken" ->
# "Saarbr?cken"), which is how a name with a real umlaut failed to match before.
function Repair-DoubleEncoding([string]$s) {
    if ([string]::IsNullOrEmpty($s) -or -not $s.Contains([string][char]0x00C3)) { return $s }
    $A = [string][char]0x00C3
    $pairs = @(
        @($A + [string][char]0x00BC, 'ü'),
        @($A + [string][char]0x00B6, 'ö'),
        @($A + [string][char]0x00A4, 'ä'),
        @($A + [string][char]0x0178, 'ß'),
        @($A + [string][char]0x201E, 'Ä'),
        @($A + [string][char]0x2013, 'Ö'),
        @($A + [string][char]0x0153, 'Ü'),
        @($A + [string][char]0x00A9, 'é')
    )
    foreach ($p in $pairs) { $s = $s.Replace($p[0], $p[1]) }
    return $s
}
function Normalize-Time([string]$t) {
    if ([string]::IsNullOrWhiteSpace($t)) { return $null }
    $t = $t.Trim()
    $ts = [TimeSpan]::Zero
    # NOTE: never cast TotalHours to [int] here - PowerShell ROUNDS on a numeric
    # cast ([int]7.5 -> 8), which silently shifts every half-hour time (07:30 ->
    # 08:30). TimeSpan.Hours is the exact hours component.
    if ([TimeSpan]::TryParse($t, [ref]$ts)) { return ('{0:00}:{1:00}' -f $ts.Hours, $ts.Minutes) }
    return $null
}
function Normalize-Window([string]$s, [string]$e) {
    $ns = Normalize-Time $s; $ne = Normalize-Time $e
    if (-not $ns -or -not $ne) { return $null }
    return "$ns-$ne"
}
function New-Window([TimeSpan]$s, [TimeSpan]$e) {
    return ('{0:00}:{1:00}-{2:00}:{3:00}' -f $s.Hours, $s.Minutes, $e.Hours, $e.Minutes)
}
function Parse-Window([string]$w) {
    if ([string]::IsNullOrWhiteSpace($w)) { return $null }
    $p = $w.Split('-')
    if ($p.Count -ne 2) { return $null }
    try { return @([TimeSpan]::Parse($p[0]), [TimeSpan]::Parse($p[1])) } catch { return $null }
}
# WicLocationMatcher.MatchesAgentTask (RepairDoubleEncoding + exact + 20-char prefix rule)
function Matches-AgentTask([string]$agentTask, $loc) {
    if ([string]::IsNullOrWhiteSpace($agentTask)) { return $false }
    $raw = $agentTask.Trim()
    $wasTruncated = $raw.Length -ge 20
    $task = Repair-DoubleEncoding $raw
    if ($wasTruncated -and $task.EndsWith([string][char]0x00C3)) { $task = $task.Substring(0, $task.Length - 1) }
    foreach ($n in @($loc.DisplayName, $loc.LocationCode, $loc.LocationCodeLegacy)) {
        if (-not [string]::IsNullOrWhiteSpace($n) -and $task -ieq $n) { return $true }
    }
    if (-not $wasTruncated -or $task.Length -eq 0) { return $false }
    foreach ($n in @($loc.DisplayName, $loc.LocationCode, $loc.LocationCodeLegacy)) {
        if (-not [string]::IsNullOrWhiteSpace($n) -and $n.StartsWith($task, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}
# WicLocationMatcher.MatchesSupportLocation
function Matches-SupportLocation([string]$sl, $loc) {
    if ([string]::IsNullOrWhiteSpace($sl)) { return $false }
    $v = Repair-DoubleEncoding $sl.Trim()
    if ($v -eq $loc.DisplayName) { return $true }
    if ($loc.City -and $v -eq $loc.City) { return $true }
    if ($v -ieq $loc.LocationCode) { return $true }
    if ($loc.LocationCodeLegacy -and $v -ieq $loc.LocationCodeLegacy) { return $true }
    return $false
}
# The centre's open intervals as TimeSpan pairs
function Get-Intervals($h) {
    $list = New-Object System.Collections.ArrayList
    if (-not $h -or $h.IsClosed) { return ,$list }
    $a = Normalize-Time $h.OpenTime;  $b = Normalize-Time $h.CloseTime
    if ($a -and $b) { [void]$list.Add(@([TimeSpan]::Parse($a), [TimeSpan]::Parse($b))) }
    $c = Normalize-Time $h.OpenTime2; $d = Normalize-Time $h.CloseTime2
    if ($c -and $d) { [void]$list.Add(@([TimeSpan]::Parse($c), [TimeSpan]::Parse($d))) }
    return ,$list
}
# WicHoursResolver.DutyWindow: first interval open .. LAST interval close
function Get-DutyWindow($h) {
    if (-not $h -or $h.IsClosed) { return $null }
    $start = if (-not [string]::IsNullOrWhiteSpace($h.OpenTime)) { $h.OpenTime } else { $h.OpenTime2 }
    $end   = if (-not [string]::IsNullOrWhiteSpace($h.CloseTime2)) { $h.CloseTime2 } else { $h.CloseTime }
    return Normalize-Window $start $end
}
# Intersection of one shift window with the union of the centre's intervals,
# reported as first-overlap-start .. last-overlap-end (the codebase's spanning
# convention, WicHoursResolver.DutyWindow).
function Get-IntersectionSpanned([string]$win, $intervals) {
    $w = Parse-Window $win
    if (-not $w) { return $null }
    $pieces = New-Object System.Collections.ArrayList
    foreach ($iv in @($intervals)) {
        $s = if ($w[0] -gt $iv[0]) { $w[0] } else { $iv[0] }
        $e = if ($w[1] -lt $iv[1]) { $w[1] } else { $iv[1] }
        if ($e -gt $s) { [void]$pieces.Add(@($s, $e)) }
    }
    if ($pieces.Count -eq 0) { return $null }
    $ps = $pieces[0][0]; $pe = $pieces[0][1]
    foreach ($p in $pieces) { if ($p[0] -lt $ps) { $ps = $p[0] }; if ($p[1] -gt $pe) { $pe = $p[1] } }
    return New-Window $ps $pe
}

# ---------------------------------------------------------------------------
# Load (SELECT only)
# ---------------------------------------------------------------------------
$serverToday = [datetime](Invoke-Scalar "SELECT CAST(GETDATE() AS date)")
$loadFrom = ([datetime]::ParseExact($ScopeFrom, 'yyyy-MM-dd', $null)).AddDays(-7 * $BaselineWeeks)
$todayBaselineFrom = $serverToday.AddDays(-(7 * $BaselineWeeks - 1))
if ($todayBaselineFrom -lt $loadFrom) { $loadFrom = $todayBaselineFrom }

Write-Host "Loading data (scope $ScopeFrom..$ScopeTo, baseline back to $($loadFrom.ToString('yyyy-MM-dd'))) ..."
$seRows = Invoke-Rows @"
SELECT se.Id, se.EmployeeId, CONVERT(varchar(10), se.ShiftDate, 23) AS D,
       se.ShiftType, se.ShiftStart, se.ShiftEnd, se.AgentTask,
       se.SourceModule, se.SourceId, se.AutoGenerated, se.ManualChangeBy, se.IsWicDuty
FROM ShiftEntries se
WHERE se.ShiftDate >= CONVERT(date, '$($loadFrom.ToString('yyyy-MM-dd'))', 23)
  AND se.ShiftDate <= CONVERT(date, '$ScopeTo', 23)
ORDER BY se.EmployeeId, se.ShiftDate, se.Id
"@
$batches = Invoke-Rows "SELECT Id, CreatedByKid FROM RosterBatches"
$locs    = Invoke-Rows "SELECT LocationCode, DisplayName, City, LocationCodeLegacy, IsActive, MinAgentsRequired FROM WicLocations"
$hours   = Invoke-Rows "SELECT Id, LocationCode, DayOfWeek, OpenTime, CloseTime, OpenTime2, CloseTime2, IsClosed, MinRequired, CONVERT(varchar(10),ExceptionDate,23) ExDate, CONVERT(varchar(10),EffectiveFrom,23) EffFrom, CONVERT(varchar(23),ManualChangeAt,121) MAt FROM WicOpeningHours"
$wicRows = Invoke-Rows @"
SELECT w.Id, w.EmployeeId, CONVERT(varchar(10), w.ShiftDate, 23) AS D, w.SupportLocation,
       w.LocationCode, w.WorkingShift, w.IsOnSite, w.IsGSDDay, w.IsOffDay, w.Task
FROM WicShiftEntries w
WHERE w.ShiftDate >= CONVERT(date, '$ScopeFrom', 23)
  AND w.ShiftDate <= CONVERT(date, '$ScopeTo', 23)
ORDER BY w.EmployeeId, w.ShiftDate, w.Id
"@

$batchKid = @{}
foreach ($b in $batches) { $batchKid[[int]$b.Id] = $b.CreatedByKid }

# index ShiftEntries by employee (+ parse dates / normalise windows once)
$seByEmp = @{}
foreach ($r in $seRows) {
    $d = [datetime]::ParseExact($r.D, 'yyyy-MM-dd', $null)
    $o = [pscustomobject]@{
        Id = [int]$r.Id; EmployeeId = $r.EmployeeId; D = $r.D; DT = $d
        Dow = [int]$d.DayOfWeek; ShiftType = $r.ShiftType; Start = $r.ShiftStart; End = $r.ShiftEnd
        Win = (Normalize-Window $r.ShiftStart $r.ShiftEnd); AgentTask = $r.AgentTask
        SourceModule = $r.SourceModule; SourceId = $r.SourceId; Auto = [bool]$r.AutoGenerated
        Manual = $r.ManualChangeBy; IsWicDuty = [bool]$r.IsWicDuty
    }
    if (-not $seByEmp.ContainsKey($r.EmployeeId)) { $seByEmp[$r.EmployeeId] = New-Object System.Collections.ArrayList }
    [void]$seByEmp[$r.EmployeeId].Add($o)
}

# index WicShiftEntries by employee|date
$wicByEmpDate = @{}
foreach ($w in $wicRows) {
    $k = "$($w.EmployeeId)|$($w.D)"
    if (-not $wicByEmpDate.ContainsKey($k)) { $wicByEmpDate[$k] = New-Object System.Collections.ArrayList }
    [void]$wicByEmpDate[$k].Add($w)
}

# index WicOpeningHours by location code
$hoursByCode = @{}
foreach ($h in $hours) {
    if (-not $hoursByCode.ContainsKey($h.LocationCode)) { $hoursByCode[$h.LocationCode] = New-Object System.Collections.ArrayList }
    [void]$hoursByCode[$h.LocationCode].Add($h)
}
function Resolve-Hours($loc, [string]$ds, [int]$dow) {
    $codes = @($loc.LocationCode); if ($loc.LocationCodeLegacy) { $codes += $loc.LocationCodeLegacy }
    $cand = New-Object System.Collections.ArrayList
    foreach ($c in $codes) { if ($hoursByCode.ContainsKey($c)) { foreach ($h in $hoursByCode[$c]) { [void]$cand.Add($h) } } }
    $exc = $cand | Where-Object { $_.ExDate -eq $ds } | Sort-Object { if ($_.MAt) { $_.MAt } else { '' } } -Descending | Select-Object -First 1
    if ($exc) { return $exc }
    return ($cand | Where-Object { -not $_.ExDate -and $_.DayOfWeek -eq $dow -and (-not $_.EffFrom -or $_.EffFrom -le $ds) } |
        Sort-Object { if ($_.EffFrom) { $_.EffFrom } else { '0001-01-01' } } -Descending | Select-Object -First 1)
}

# ---------------------------------------------------------------------------
# Usual shift (c)
# ---------------------------------------------------------------------------
function Get-UsualShift($empRows, [datetime]$date) {
    # The baseline window is the 8 weeks = 56 days ending on the anchor day.
    #   BaselineAnchor 'Today' (default) -> the last 8 weeks up to the server day.
    #       This is what "u poslednjih 8 nedelja" says, and it is also the
    #       definition already used by Tools\Backfill-WicDutyCandidates.ps1
    #       ("usual-shift window, in weeks, ending today").
    #   BaselineAnchor 'Row' -> the 8 weeks immediately before the row's own date
    #       (sensitivity variant, reported for comparison only).
    if ($BaselineAnchor -eq 'Today') {
        $from = $serverToday.AddDays(-(7 * $BaselineWeeks - 1))
        $to   = $serverToday
    } else {
        $from = $date.AddDays(-7 * $BaselineWeeks)
        $to   = $date.AddDays(-1)
    }
    $dow  = [int]$date.DayOfWeek
    $cand = New-Object System.Collections.ArrayList
    foreach ($r in $empRows) {
        if ($r.DT -lt $from -or $r.DT -gt $to) { continue }
        if (-not $r.Manual -and $r.ShiftType -ne 'WORKING') { continue }
        if (-not $r.Win) { continue }
        [void]$cand.Add($r)
    }
    if ($cand.Count -eq 0) { return $null }
    foreach ($scope in @('DOW','ALL')) {
        $sub = if ($scope -eq 'DOW') { @($cand | Where-Object { $_.Dow -eq $dow }) } else { @($cand) }
        if ($sub.Count -eq 0) { continue }
        $stat = @{}
        foreach ($r in $sub) {
            if (-not $stat.ContainsKey($r.Win)) { $stat[$r.Win] = [pscustomobject]@{ Window = $r.Win; Count = 0; Last = '' } }
            $stat[$r.Win].Count++
            if ($r.D -gt $stat[$r.Win].Last) { $stat[$r.Win].Last = $r.D }
        }
        $ranked = $stat.Values | Sort-Object `
            @{Expression = { $_.Count }; Descending = $true }, `
            @{Expression = { $_.Last };  Descending = $true }, `
            @{Expression = { $_.Window }; Descending = $false }
        $top = @($ranked)[0]
        $share = $top.Count / $sub.Count
        if ($top.Count -ge $MinOccurrences -and $share -ge $MinShare) {
            return [pscustomobject]@{
                Window = $top.Window; Count = $top.Count; Total = $sub.Count
                Share = $share; Scope = $scope; Candidates = $cand.Count
            }
        }
    }
    return $null
}

# ---------------------------------------------------------------------------
# Evaluate every WIC_DUTY row in scope
# ---------------------------------------------------------------------------
Write-Host "Evaluating ..."
$results = New-Object System.Collections.ArrayList
$scopeRows = @($seRows | Where-Object { $_.ShiftType -eq 'WIC_DUTY' -and [datetime]::ParseExact($_.D, 'yyyy-MM-dd', $null) -ge [datetime]::ParseExact($ScopeFrom, 'yyyy-MM-dd', $null) -and [datetime]::ParseExact($_.D, 'yyyy-MM-dd', $null) -le [datetime]::ParseExact($ScopeTo, 'yyyy-MM-dd', $null) })

foreach ($r in $scopeRows) {
    $row = $seByEmp[$r.EmployeeId] | Where-Object { $_.Id -eq [int]$r.Id } | Select-Object -First 1
    $d   = $row.DT
    $oldWin = $row.Win

    $reason = ''; $loc = $null; $hRow = $null; $primary = $null; $duty = $null
    $traceKind = ''; $usual = $null; $newWin = $null; $wicRow = $null; $newWic = $null
    $wicCount = 0

    if ($d -le $serverToday) {
        $reason = 'DANAS_ILI_PROSLOST'
    } elseif ($row.Manual) {
        $reason = 'RUCNO'
    } else {
        $kid = if ($r.SourceId -and $batchKid.ContainsKey([int]$r.SourceId)) { $batchKid[[int]$r.SourceId] } else { $null }
        $isSystemBatch = ($row.SourceModule -eq 'Roster') -and $row.Auto -and (-not [string]::IsNullOrWhiteSpace($kid)) -and ($kid -like 'SYSTEM_*' -or $kid -like 'SYSTEM_*')
        if (-not $isSystemBatch) {
            $reason = 'NIJE_AUTO_BATCH'
        } else {
            # ---- centre ----
            $matches = @($locs | Where-Object { Matches-AgentTask $row.AgentTask $_ })
            if ($matches.Count -eq 1) { $loc = $matches[0] }
            elseif ($matches.Count -gt 1) { $loc = $matches | Where-Object { $_.IsActive } | Select-Object -First 1; if (-not $loc) { $loc = $matches[0] } }
            if (-not $loc) {
                # fallback: the paired on-site WIC row names the centre
                $pairs = @($wicByEmpDate["$($row.EmployeeId)|$($row.D)"] | Where-Object { $_.IsOnSite })
                $cand = @()
                foreach ($p in $pairs) { $m = @($locs | Where-Object { Matches-SupportLocation $p.SupportLocation $_ }); if ($m.Count -eq 1) { $cand += $m[0] } }
                $cand = @($cand | Sort-Object LocationCode -Unique)
                if ($cand.Count -eq 1) { $loc = $cand[0] }
            }
            if (-not $loc) { $reason = 'CENTAR_NIJE_JASAN' }
        }
    }

    if (-not $reason) {
        $hRow = Resolve-Hours $loc $row.D $row.Dow
        if (-not $hRow -or $hRow.IsClosed) { $reason = 'NEMA_RADNOG_VREMENA' }
        else {
            $primary = Normalize-Window $hRow.OpenTime $hRow.CloseTime
            $duty    = Get-DutyWindow $hRow
            if ($oldWin -and $primary -and $oldWin -eq $primary) { $traceKind = 'PRIMARY' }
            elseif ($oldWin -and $duty -and $oldWin -eq $duty) { $traceKind = 'DUTY' }
            if (-not $traceKind) { $reason = 'NIJE_TRAG_GRESKE' }
        }
    }

    if (-not $reason) {
        $usual = Get-UsualShift $seByEmp[$row.EmployeeId] $d
        if (-not $usual) { $reason = 'NEMA_JASNE_SMENE' } else { $newWin = $usual.Window }
    }

    if (-not $reason) {
        if ($newWin -eq $oldWin) { $reason = 'VEC_ISPRAVNO' }
    }

    if (-not $reason) {
        # ---- paired WicShiftEntries row for the same centre ----
        $pairs = @($wicByEmpDate["$($row.EmployeeId)|$($row.D)"] | Where-Object { $_.IsOnSite -and (Matches-SupportLocation $_.SupportLocation $loc) })
        $wicCount = $pairs.Count
        if ($wicCount -eq 0) { $reason = 'PRAZAN_PRESEK_NEMA_WIC' }
        elseif ($wicCount -gt 1) { $reason = 'VISE_WIC_REDOVA' }
        else {
            $wicRow = $pairs[0]
            $newWic = Get-IntersectionSpanned $newWin (Get-Intervals $hRow)
            if (-not $newWic) { $reason = 'PRAZAN_PRESEK' }
        }
    }

    [void]$results.Add([pscustomobject]@{
        SeId          = $row.Id
        EmployeeId    = $row.EmployeeId
        Date          = $row.D
        Month         = $row.D.Substring(0, 7)
        Dow           = $row.Dow
        Centre        = if ($loc) { $loc.DisplayName } else { $null }
        LocationCode  = if ($loc) { $loc.LocationCode } else { $null }
        AgentTask     = $row.AgentTask
        OldStart      = $row.Start
        OldEnd        = $row.End
        OldWin        = $oldWin
        CentrePrimary = $primary
        CentreDuty    = $duty
        TraceKind     = $traceKind
        UsualWin      = if ($usual) { $usual.Window } else { $null }
        UsualCount    = if ($usual) { $usual.Count } else { 0 }
        UsualTotal    = if ($usual) { $usual.Total } else { 0 }
        UsualShare    = if ($usual) { [math]::Round($usual.Share, 3) } else { $null }
        UsualScope    = if ($usual) { $usual.Scope } else { $null }
        NewStart      = if ($newWin) { $newWin.Split('-')[0] } else { $null }
        NewEnd        = if ($newWin) { $newWin.Split('-')[1] } else { $null }
        NewWin        = $newWin
        WicId         = if ($wicRow) { [int]$wicRow.Id } else { $null }
        WicCount      = $wicCount
        OldWicShift   = if ($wicRow) { $wicRow.WorkingShift } else { $null }
        NewWicShift   = $newWic
        SourceKid     = if ($r.SourceId -and $batchKid.ContainsKey([int]$r.SourceId)) { $batchKid[[int]$r.SourceId] } else { $null }
        SourceId      = $r.SourceId
        Reason        = $reason
        Fixable       = [string]::IsNullOrEmpty($reason)
    })
}

$fixable = @($results | Where-Object { $_.Fixable -and $_.NewWicShift })
$noop    = @($results | Where-Object { $_.Reason -eq 'VEC_ISPRAVNO' })
$rtmReasons = @('NEMA_JASNE_SMENE','PRAZAN_PRESEK','CENTAR_NIJE_JASAN','VISE_WIC_REDOVA','NEMA_RADNOG_VREMENA','PRAZAN_PRESEK_NEMA_WIC')
$rtm = @($results | Where-Object { $rtmReasons -contains $_.Reason })

# ---------------------------------------------------------------------------
# Report
# ---------------------------------------------------------------------------
$out = New-Object System.Collections.ArrayList
function P([string]$s = "") { [void]$out.Add($s) }

P "SHIFT_MISMATCH REPAIR - $Mode"
P "generated        : $([DateTime]::Now.ToString('yyyy-MM-dd HH:mm:ss'))  (server today $($serverToday.ToString('yyyy-MM-dd')))"
P "scope            : ShiftEntries ShiftType='WIC_DUTY', ShiftDate $ScopeFrom .. $ScopeTo"
P "rule a           : SourceModule='Roster' AND AutoGenerated=1 AND ManualChangeBy empty AND RosterBatches.CreatedByKid LIKE 'SYSTEM_*'"
P "rule b           : ShiftStart-ShiftEnd exactly the centre window for that date (WicOpeningHours primary interval OpenTime-CloseTime, or the resolver DutyWindow)"
P "rule c           : usual shift = most frequent window over the agent manual + WORKING rows of the $BaselineWeeks weeks (56 days) ending $(if ($BaselineAnchor -eq 'Today') { "on the server day ($($serverToday.ToString('yyyy-MM-dd')), i.e. $($serverToday.AddDays(-(7*$BaselineWeeks-1)).ToString('yyyy-MM-dd'))..$($serverToday.ToString('yyyy-MM-dd')))" } else { 'the day before the row date' }), same weekday; >= $MinOccurrences occurrences and share >= $($MinShare.ToString('0.00')); fallback all days"
P "wic pairing      : WicShiftEntries EmployeeId+ShiftDate, IsOnSite=1, SupportLocation == the same centre"
P "provenance       : ManualChangeBy='$ManualChangeByKid' on every repaired row (never S60028)"
P ""
P "WIC_DUTY rows in scope          : $($results.Count)"
P "REPAIR SET (a+b+c, non-empty)   : $($fixable.Count)"
P "left alone - VEC_ISPRAVNO       : $($noop.Count)"
P ""
P "=== 1) LEFT ALONE BY REASON ==="
foreach ($g in ($results | Group-Object Reason | Sort-Object Count -Descending)) {
    P ("  {0,-24} {1,6}" -f $(if ($g.Name) { $g.Name } else { '(none)' }), $g.Count)
}
P ""
P "=== 2) REPAIR SET BY MONTH ==="
P ("{0,-9} {1,7}" -f "month", "rows")
foreach ($g in ($fixable | Group-Object Month | Sort-Object Name)) { P ("{0,-9} {1,7}" -f $g.Name, $g.Count) }
P ("{0,-9} {1,7}" -f "TOTAL", $fixable.Count)
P ""
P "=== 2b) REPAIR SET BY SOURCE BATCH ==="
foreach ($g in ($fixable | Group-Object SourceKid | Sort-Object Count -Descending)) { P ("  {0,-20} {1,6}" -f $g.Name, $g.Count) }
P ""
P "=== 2c) REPAIR SET BY CENTRE ==="
foreach ($g in ($fixable | Group-Object Centre | Sort-Object Count -Descending)) { P ("  {0,-28} {1,6}" -f $g.Name, $g.Count) }
P ""
P "=== 3) 10 EXAMPLES (EmployeeId, date, centre, old shift, new shift, new WorkingShift) ==="
P ("{0,-9} {1,-10} {2,-26} {3,-13} {4,-13} {5,-13} {6,-22}" -f "emp","date","centre","old shift","new shift","new WorkingShift","trace/usual")
foreach ($x in ($fixable | Sort-Object Date, EmployeeId | Select-Object -First 10)) {
    $extra = "$($x.TraceKind)/$($x.UsualScope) n=$($x.UsualCount)/$($x.UsualTotal) p=$($x.UsualShare)"
    P ("{0,-9} {1,-10} {2,-26} {3,-13} {4,-13} {5,-13} {6,-22}" -f $x.EmployeeId, $x.Date, $x.Centre, $x.OldWin, $x.NewWin, $x.NewWicShift, $extra)
}
P ""
P "=== 4) RTM LIST (rows that must NOT be touched automatically) ==="
P "count: $($rtm.Count)"
P ""
P "-- 4a) RTM grouped: employee + centre + reason --"
P ("{0,-9} {1,-26} {2,-20} {3,6} {4,-10} {5,-10}" -f "emp","centre","reason","rows","first","last")
foreach ($g in ($rtm | Group-Object EmployeeId, Centre, Reason | Sort-Object Name)) {
    $rows = $g.Group | Sort-Object Date
    P ("{0,-9} {1,-26} {2,-20} {3,6} {4,-10} {5,-10}" -f $rows[0].EmployeeId, $(if ($rows[0].Centre) { $rows[0].Centre } else { '-' }), $rows[0].Reason, $rows.Count, $rows[0].Date, $rows[-1].Date)
}
P ""
P "-- 4b) RTM row by row (EmployeeId, date, centre, current shift, reason) --"
P ("{0,-9} {1,-10} {2,-26} {3,-13} {4,-22} {5}" -f "emp","date","centre","current shift","reason","usual?")
foreach ($x in ($rtm | Sort-Object EmployeeId, Date)) {
    P ("{0,-9} {1,-10} {2,-26} {3,-13} {4,-22} {5}" -f $x.EmployeeId, $x.Date, $(if ($x.Centre) { $x.Centre } else { '-' }), $(if ($x.OldWin) { $x.OldWin } else { "$($x.OldStart)-$($x.OldEnd)" }), $x.Reason, $(if ($x.UsualWin) { $x.UsualWin } else { '-' }))
}
P ""
P "=== 5) USUAL-SHIFT EVIDENCE per employee in the repair set (auditable) ==="
P "manual = rows with ManualChangeBy set; work = WORKING rows; both must carry a time."
P ("{0,-9} {1,-13} {2,5} {3,5} {4,-6} {5,-13} {6,5} {7,-13} {8,5} {9}" -f "emp","usual","cnt","tot","scope","manualTop","mCnt","workTop","wCnt","conflict")
if ($BaselineAnchor -eq 'Today') { $evFrom = $serverToday.AddDays(-(7 * $BaselineWeeks - 1)); $evTo = $serverToday } else { $evFrom = $null; $evTo = $null }
$review = New-Object System.Collections.ArrayList
foreach ($eid in ($fixable | Select-Object -ExpandProperty EmployeeId -Unique | Sort-Object)) {
    $fx = @($fixable | Where-Object { $_.EmployeeId -eq $eid })
    $win = $fx[0].NewWin
    if ($BaselineAnchor -ne 'Today') { continue }   # evidence table is defined for the fixed baseline only
    $rowsE = @($seByEmp[$eid] | Where-Object { $_.DT -ge $evFrom -and $_.DT -le $evTo })
    $man = @($rowsE | Where-Object { $_.Manual -and $_.Win })
    $wrk = @($rowsE | Where-Object { -not $_.Manual -and $_.ShiftType -eq 'WORKING' -and $_.Win })
    $mTop = '-'; $mCnt = 0
    if ($man.Count) { $g = $man | Group-Object Win | Sort-Object Count -Descending | Select-Object -First 1; $mTop = $g.Name; $mCnt = $g.Count }
    $wTop = '-'; $wCnt = 0
    if ($wrk.Count) { $g = $wrk | Group-Object Win | Sort-Object Count -Descending | Select-Object -First 1; $wTop = $g.Name; $wCnt = $g.Count }
    $conflict = if ($mCnt -gt 0 -and $mTop -ne $win -and $mCnt -ge 3 -and ($mCnt / [math]::Max(1, $man.Count)) -ge $MinShare) { 'MANUAL-EVIDENCE-DIFFERS' } else { '' }
    P ("{0,-9} {1,-13} {2,5} {3,5} {4,-6} {5,-13} {6,5} {7,-13} {8,5} {9}" -f $eid, $win, $fx[0].UsualCount, $fx[0].UsualTotal, $fx[0].UsualScope, $mTop, $mCnt, $wTop, $wCnt, $conflict)
    if ($conflict) { [void]$review.Add([pscustomobject]@{ EmployeeId = $eid; UsualWin = $win; Pooled = "$($fx[0].UsualCount)/$($fx[0].UsualTotal)"; ManualTop = $mTop; ManualCount = $mCnt; WorkTop = $wTop; WorkCount = $wCnt; Rows = $fx.Count }) }
}
P ""
P "-- 5b) REVIEW: employees whose manual-only evidence ALSO has a >=$MinOccurrences / >=$($MinShare.ToString('0.00')) majority that DIFFERS from the pooled answer --"
if ($review.Count -eq 0) { P "  (none)" } else {
    P ("{0,-9} {1,-13} {2,8} {3,-13} {4,6} {5,-13} {6,6} {7,6}" -f "emp","usual(pooled)","pooled","manualTop","mCnt","workTop","wCnt","rows")
    foreach ($v in $review) { P ("{0,-9} {1,-13} {2,8} {3,-13} {4,6} {5,-13} {6,6} {7,6}" -f $v.EmployeeId, $v.UsualWin, $v.Pooled, $v.ManualTop, $v.ManualCount, $v.WorkTop, $v.WorkCount, $v.Rows) }
    $review | Export-Csv (Join-Path $OutDir 'shift-mismatch-review.csv') -NoTypeInformation -Encoding UTF8
}
P ""
P "=== 6) WIC WorkingShift effect ==="
P ("  ShiftEntries rows repaired            : {0}" -f $fixable.Count)
P ("  WicShiftEntries WorkingShift updated  : {0}" -f @($fixable | Where-Object { $_.NewWicShift -ne $_.OldWicShift }).Count)
P ("  WicShiftEntries WorkingShift unchanged: {0}" -f @($fixable | Where-Object { $_.NewWicShift -eq $_.OldWicShift }).Count)

($out -join "`r`n") | Set-Content -Path $ReportFile -Encoding UTF8
$results | Sort-Object Date, EmployeeId, SeId |
    Select-Object SeId,EmployeeId,Date,Month,Centre,LocationCode,AgentTask,OldWin,CentrePrimary,CentreDuty,TraceKind,
        UsualWin,UsualCount,UsualTotal,UsualShare,UsualScope,NewWin,WicId,OldWicShift,NewWicShift,SourceKid,SourceId,Reason,Fixable |
    Export-Csv -Path $AllCsv -NoTypeInformation -Encoding UTF8
$rtm | Sort-Object EmployeeId, Date |
    Select-Object EmployeeId,Date,Month,Centre,LocationCode,OldWin,UsualWin,UsualCount,UsualTotal,UsualShare,Reason,SeId,WicId,SourceKid |
    Export-Csv -Path $RtmCsv -NoTypeInformation -Encoding UTF8

# The plan file is the dry-run snapshot the Apply guard compares against.
$planFields = @('SeId','EmployeeId','Date','Centre','LocationCode','OldStart','OldEnd','OldWin','CentrePrimary','CentreDuty','TraceKind','UsualWin','UsualCount','UsualTotal','UsualShare','UsualScope','NewStart','NewEnd','NewWin','WicId','OldWicShift','NewWicShift','SourceKid','SourceId')
$fixable | Sort-Object Date, EmployeeId, SeId | Select-Object $planFields |
    Export-Csv -Path $PlanFile -NoTypeInformation -Encoding UTF8

Write-Host ""
Write-Host "REPAIR SET : $($fixable.Count)"
Write-Host "RTM LIST   : $($rtm.Count)"
Write-Host "report     : $ReportFile"
Write-Host "plan       : $PlanFile"
Write-Host "all        : $AllCsv"
Write-Host "rtm        : $RtmCsv"
if ($isDryRun) {
    Write-Host "DRY RUN - no writes."
    $conn.Close()
    return
}

# ---------------------------------------------------------------------------
# APPLY
# ---------------------------------------------------------------------------
if (-not (Test-Path $PlanFile)) { throw "APPLY REFUSED: plan file not found: $PlanFile" }
$plan = @(Import-Csv -Path $PlanFile)
if ($plan.Count -eq 0) { throw "APPLY REFUSED: plan is empty." }
if ($ExpectedFixCount -le 0) { throw "APPLY REFUSED: pass -ExpectedFixCount (the dry-run REPAIR SET size)." }
if ($plan.Count -ne $ExpectedFixCount) { throw ("APPLY REFUSED: plan has {0} row(s), expected {1}." -f $plan.Count, $ExpectedFixCount) }

$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$root = Join-Path $RollbackRoot ("shift-fix-{0}" -f $stamp)
New-Item -ItemType Directory -Force -Path $root | Out-Null
Write-Host "Backup root: $root"

$seIds  = @($plan | ForEach-Object { [int]$_.SeId })
$wicIds = @($plan | Where-Object { $_.WicId } | ForEach-Object { [int]$_.WicId } | Sort-Object -Unique)
$inSe  = ($seIds -join ',')
$inWic = if ($wicIds.Count) { ($wicIds -join ',') } else { '0' }

$seBackup  = Invoke-Rows "SELECT * FROM ShiftEntries WHERE Id IN ($inSe)"
$wicBackup = Invoke-Rows "SELECT * FROM WicShiftEntries WHERE Id IN ($inWic)"
$seBackup  | Export-Csv (Join-Path $root 'ShiftEntries.csv') -NoTypeInformation -Encoding UTF8
$wicBackup | Export-Csv (Join-Path $root 'WicShiftEntries.csv') -NoTypeInformation -Encoding UTF8

$hashLines = New-Object System.Collections.ArrayList
foreach ($f in @('ShiftEntries.csv','WicShiftEntries.csv')) {
    $h = (Get-FileHash -Path (Join-Path $root $f) -Algorithm SHA256).Hash
    [void]$hashLines.Add("$h  $f")
}
($hashLines -join "`r`n") | Set-Content -Path (Join-Path $root 'SHA256SUMS.txt') -Encoding ASCII

$rb = New-Object System.Collections.ArrayList
[void]$rb.Add("-- ROLLBACK for shift-fix-$stamp (generated $([DateTime]::Now.ToString('yyyy-MM-dd HH:mm:ss')))")
[void]$rb.Add("-- Restores ShiftEntries.ShiftStart/ShiftEnd + manual provenance and WicShiftEntries.WorkingShift")
[void]$rb.Add("-- to their pre-fix values for every row changed by Fix-ShiftMismatch.ps1.")
[void]$rb.Add("-- NOT executed by the script. Run it by hand only if the fix must be undone.")
[void]$rb.Add("SET XACT_ABORT ON;")
[void]$rb.Add("BEGIN TRAN;")
foreach ($b in $seBackup) {
    $ss = if ($null -eq $b.ShiftStart) { 'NULL' } else { "N'" + ([string]$b.ShiftStart).Replace("'", "''") + "'" }
    $se = if ($null -eq $b.ShiftEnd)   { 'NULL' } else { "N'" + ([string]$b.ShiftEnd).Replace("'", "''") + "'" }
    $mb = if ($null -eq $b.ManualChangeBy) { 'NULL' } else { "N'" + ([string]$b.ManualChangeBy).Replace("'", "''") + "'" }
    $ma = if ($null -eq $b.ManualChangeAt) { 'NULL' } else { "CONVERT(datetime,'" + ([datetime]$b.ManualChangeAt).ToString('yyyy-MM-dd HH:mm:ss.fff') + "',121)" }
    $mn = if ($null -eq $b.ManualChangeNote) { 'NULL' } else { "N'" + ([string]$b.ManualChangeNote).Replace("'", "''") + "'" }
    [void]$rb.Add("UPDATE ShiftEntries SET ShiftStart=$ss, ShiftEnd=$se, ManualChangeBy=$mb, ManualChangeAt=$ma, ManualChangeNote=$mn WHERE Id=$($b.Id);")
}
foreach ($b in $wicBackup) {
    $ws = if ($null -eq $b.WorkingShift) { 'NULL' } else { "N'" + ([string]$b.WorkingShift).Replace("'", "''") + "'" }
    [void]$rb.Add("UPDATE WicShiftEntries SET WorkingShift=$ws WHERE Id=$($b.Id);")
}
[void]$rb.Add("COMMIT;")
($rb -join "`r`n") | Set-Content -Path (Join-Path $root 'rollback.sql') -Encoding UTF8
($plan | Select-Object SeId,EmployeeId,Date,Centre,OldWin,NewWin,OldWicShift,NewWicShift) |
    Export-Csv (Join-Path $root 'plan-applied.csv') -NoTypeInformation -Encoding UTF8

# ---- one transaction, per-row guard, rollback on any failure ----
$applied = 0; $skipped = New-Object System.Collections.ArrayList
$before = [int](Invoke-Scalar "SELECT COUNT(*) FROM ShiftEntries WHERE ShiftStart IS NOT NULL")
$tx = $conn.BeginTransaction()
try {
    $guard = @{}
    foreach ($id in $seIds) { $guard[$id] = $null }
    $cmd = $conn.CreateCommand(); $cmd.Transaction = $tx
    $cmd.CommandText = "SELECT Id, EmployeeId, ShiftStart, ShiftEnd, SourceModule, SourceId, AutoGenerated, ManualChangeBy FROM ShiftEntries WITH (UPDLOCK, HOLDLOCK) WHERE Id IN ($inSe)"
    $rdr = $cmd.ExecuteReader()
    while ($rdr.Read()) {
        $id = [int]$rdr.GetValue(0)
        $guard[$id] = [pscustomobject]@{
            EmployeeId = [string]$rdr.GetValue(1)
            ShiftStart = if ($rdr.IsDBNull(2)) { $null } else { [string]$rdr.GetValue(2) }
            ShiftEnd   = if ($rdr.IsDBNull(3)) { $null } else { [string]$rdr.GetValue(3) }
            SourceModule = if ($rdr.IsDBNull(4)) { $null } else { [string]$rdr.GetValue(4) }
            SourceId   = if ($rdr.IsDBNull(5)) { $null } else { [int]$rdr.GetValue(5) }
            Auto       = [bool]$rdr.GetValue(6)
            Manual     = if ($rdr.IsDBNull(7)) { $null } else { [string]$rdr.GetValue(7) }
        }
    }
    $rdr.Close()
    $guardWic = @{}
    foreach ($id in $wicIds) { $guardWic[$id] = $null }
    if ($wicIds.Count) {
        $cmd = $conn.CreateCommand(); $cmd.Transaction = $tx
        $cmd.CommandText = "SELECT Id, WorkingShift FROM WicShiftEntries WITH (UPDLOCK, HOLDLOCK) WHERE Id IN ($inWic)"
        $rdr = $cmd.ExecuteReader()
        while ($rdr.Read()) { $guardWic[[int]$rdr.GetValue(0)] = if ($rdr.IsDBNull(1)) { $null } else { [string]$rdr.GetValue(1) } }
        $rdr.Close()
    }

    foreach ($p in ($plan | Sort-Object Date, EmployeeId)) {
        $id = [int]$p.SeId
        $cur = $guard[$id]
        $why = $null
        if (-not $cur) { $why = 'ROW_MISSING' }
        elseif ($cur.EmployeeId -ne $p.EmployeeId) { $why = 'EMPLOYEE_CHANGED' }
        elseif ($cur.ShiftStart -ne $p.OldStart -or $cur.ShiftEnd -ne $p.OldEnd) { $why = 'SHIFT_CHANGED' }
        elseif (-not [string]::IsNullOrWhiteSpace($cur.Manual)) { $why = 'NOW_MANUAL' }
        elseif (-not $cur.Auto -or $cur.SourceModule -ne 'Roster') { $why = 'SOURCE_CHANGED' }
        elseif (([string]$cur.SourceId) -ne ([string]$p.SourceId)) { $why = 'BATCH_CHANGED' }
        if (-not $why -and $p.WicId) {
            $wid = [int]$p.WicId
            if (-not $guardWic.ContainsKey($wid) -or $null -eq $guardWic[$wid] -and $null -ne $p.OldWicShift) { $why = 'WIC_ROW_MISSING' }
            elseif (([string]$guardWic[$wid]) -ne ([string]$p.OldWicShift)) { $why = 'WIC_SHIFT_CHANGED' }
        }
        if ($why) { [void]$skipped.Add([pscustomobject]@{ SeId = $id; EmployeeId = $p.EmployeeId; Date = $p.Date; Why = $why }); continue }

        $cmd = $conn.CreateCommand(); $cmd.Transaction = $tx
        $cmd.CommandText = @"
UPDATE ShiftEntries
   SET ShiftStart = @s, ShiftEnd = @e,
       ManualChangeBy = @by, ManualChangeAt = SYSUTCDATETIME(), ManualChangeNote = @note
 WHERE Id = @id
"@
        foreach ($pv in @{ '@s' = $p.NewStart; '@e' = $p.NewEnd; '@by' = $ManualChangeByKid; '@note' = $FixNote; '@id' = $id }.GetEnumerator()) {
            $par = $cmd.CreateParameter(); $par.ParameterName = $pv.Key; $par.Value = $pv.Value; [void]$cmd.Parameters.Add($par)
        }
        if ($cmd.ExecuteNonQuery() -ne 1) { throw "ShiftEntries Id=$id update affected != 1 row" }

        if ($p.WicId) {
            $cmd = $conn.CreateCommand(); $cmd.Transaction = $tx
            $cmd.CommandText = "UPDATE WicShiftEntries SET WorkingShift = @ws WHERE Id = @id"
            foreach ($pv in @{ '@ws' = $p.NewWicShift; '@id' = [int]$p.WicId }.GetEnumerator()) {
                $par = $cmd.CreateParameter(); $par.ParameterName = $pv.Key; $par.Value = $pv.Value; [void]$cmd.Parameters.Add($par)
            }
            if ($cmd.ExecuteNonQuery() -ne 1) { throw "WicShiftEntries Id=$($p.WicId) update affected != 1 row" }
        }
        $applied++
    }
    $tx.Commit()
} catch {
    $tx.Rollback()
    Write-Host "APPLY FAILED - transaction ROLLED BACK: $($_.Exception.Message)"
    throw
}
$after = [int](Invoke-Scalar "SELECT COUNT(*) FROM ShiftEntries WHERE ShiftStart IS NOT NULL")

[void]$out.Add("")
[void]$out.Add("=== 7) APPLY RESULT ===")
[void]$out.Add("backup root : $root")
[void]$out.Add("applied     : $applied")
[void]$out.Add("skipped     : $($skipped.Count)")
foreach ($s in $skipped) { [void]$out.Add("  SKIPPED SeId=$($s.SeId) emp=$($s.EmployeeId) date=$($s.Date) why=$($s.Why)") }
if ($skipped.Count) { $skipped | Export-Csv (Join-Path $root 'skipped.csv') -NoTypeInformation -Encoding UTF8 }
($out -join "`r`n") | Set-Content -Path $ReportFile -Encoding UTF8

$conn.Close()
Write-Host "APPLIED $applied row(s); skipped $($skipped.Count). Backup: $root"
